   Visualizzazione dei campi di errorInfo() per una connessione PDO_ODBC a un database DB2


<?php
/* Provoca un errore -- sintassi SQL non valida */
$stmt = $dbh->prepare('bogus sql');
if (!$stmt) {
    echo "\nPDO::errorInfo():\n";
    print_r($dbh->errorInfo());
}
?>


    &example.outputs;


PDO::errorInfo():
Array
(
    [0] => HY000
    [1] => 1
    [2] => near "bogus": syntax error
)
